R.drawMiniTank(ctx,CANVAS_W/2-40+8+i*20,34,'#4d7a3a');const icons=Math.min(game.enemiesRemaining,20);for(let i=0;i<icons;i++){const col=i%10,row=Math.floor(i/10);R.drawMiniEnemy(ctx,CANVAS_W-16-(10-col)*14,14+row*16,'#8d8d8d');}
