function drawGameover(ctx,game){ctx.fillStyle='rgba(8,8,12,0.92)';ctx.fillRect(0,0,CANVAS_W,CANVAS_H);if(game.gameoverReason==='base')R.drawEagleFallen(ctx,CANVAS_W/2,85);ctx.textAlign='center';ctx.font='bold 34px "Courier New", monospace';ctx.fillStyle='#c85050';ctx.fillText(game.gameoverReason==='base'?'ШТАБ ПАЛ':'ТАНК ПОДБИТ',CANVAS_W/2,150);ctx.font='16px "Courier New", monospace';ctx.fillStyle='#e8e8f0';ctx.fillText('СЧЁТ: '+game.engine.stats.score,CANVAS_W/2,220);ctx.fillText('ДОСТИГНУТ УРОВЕНЬ: '+game.level,CANVAS_W/2,250);ctx.font='13px "Courier New", monospace';if(Math.sin(Date.now()/400)>0){ctx.fillStyle='#e8c840';ctx.fillText('ПРОБЕЛ — В МЕНЮ',CANVAS_W/2,330);}
ctx.textAlign='left';}
